import React, { useEffect, useRef, useState } from 'react'
import { BrowserRouter, NavLink, Route, Routes, useLocation, useNavigate } from 'react-router-dom'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity as ActivityIcon, AlertTriangle, ArrowDownRight, ArrowUpRight, BarChart3, Bell, Boxes, CarFront, Check, ChevronRight, CircleGauge, ClipboardList, CloudDownload, FileBarChart, Gauge, Hash, LayoutDashboard, Menu, Package, Pencil, Plus, QrCode, RefreshCw, Search, Settings, ShieldCheck, ShoppingCart, Truck, UserRound, Users, WalletCards, X } from 'lucide-react'
import { activities, weeklyFlow } from './data'
import { useFleetFlowData } from './hooks/useFleetFlowData'
import { Product, InventoryItem, Shipment, Dispatch, Order, Vehicle, Driver, Marketer } from './types'
import { Avatar, Badge, Button, Card, ConfirmButton, EmptyState, Field, Modal, SearchBox, SectionHeader, Select, StatCard, Tabs } from './components'
import './styles.css'
import './polish.css'

declare global { interface Window { google?: any } }

const money = (n:number) => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n)
const number = (n:number) => new Intl.NumberFormat('en-IN').format(n)

const navItems = [
  {label:'Dashboard',to:'/',icon:LayoutDashboard}, {label:'Products',to:'/products',icon:Package}, {label:'Inventory',to:'/inventory',icon:Boxes},
  {label:'Incoming Stock',to:'/incoming',icon:ArrowDownRight}, {label:'Outgoing Stock',to:'/outgoing',icon:ArrowUpRight}, {label:'Orders',to:'/orders',icon:ShoppingCart},
  {label:'Vehicles',to:'/vehicles',icon:Truck}, {label:'Drivers',to:'/drivers',icon:UserRound}, {label:'QR Management',to:'/qr-management',icon:QrCode},
  {label:'Live Tracking',to:'/tracking',icon:CircleGauge}, {label:'Marketers',to:'/marketers',icon:Users}, {label:'Reports',to:'/reports',icon:FileBarChart}, {label:'Settings',to:'/settings',icon:Settings}
]

function App(){
  const { products, inventory, shipments, dispatches, orders, vehicles, drivers, marketers, setProducts, setShipments, setDispatches, setOrders, setVehicles, setDrivers, setMarketers, source, loading } = useFleetFlowData()
  return <BrowserRouter><AppShell dataSource={source} loading={loading}><Routes>
    <Route path="/" element={<Dashboard products={products} inventory={inventory} shipments={shipments} dispatches={dispatches} orders={orders} vehicles={vehicles}/>} />
    <Route path="/products" element={<ProductsPage products={products} setProducts={setProducts}/>}/>
    <Route path="/inventory" element={<InventoryPage products={products} inventory={inventory}/>}/>
    <Route path="/incoming" element={<IncomingPage shipments={shipments} setShipments={setShipments}/>}/>
    <Route path="/outgoing" element={<OutgoingPage dispatches={dispatches} setDispatches={setDispatches}/>}/>
    <Route path="/orders" element={<OrdersPage orders={orders} setOrders={setOrders} marketers={marketers}/>}/>
    <Route path="/vehicles" element={<VehiclesPage vehicles={vehicles} setVehicles={setVehicles}/>}/>
    <Route path="/drivers" element={<DriversPage drivers={drivers} setDrivers={setDrivers}/>}/>
    <Route path="/qr-management" element={<QRPage shipments={shipments}/>}/>
    <Route path="/tracking" element={<TrackingPage vehicles={vehicles}/>}/>
    <Route path="/marketers" element={<MarketersPage marketers={marketers} setMarketers={setMarketers}/>}/>
    <Route path="/reports" element={<ReportsPage inventory={inventory} products={products} shipments={shipments} dispatches={dispatches}/>}/>
    <Route path="/settings" element={<SettingsPage/>}/>
    <Route path="*" element={<Dashboard products={products} inventory={inventory} shipments={shipments} dispatches={dispatches} orders={orders} vehicles={vehicles}/>}/>
  </Routes></AppShell></BrowserRouter>
}

function AppShell({children,dataSource,loading}:{children:React.ReactNode;dataSource:'supabase'|'mock';loading:boolean}){
  const location=useLocation(); const navigate=useNavigate(); const [mobileOpen,setMobileOpen]=useState(false); const [globalQ,setGlobalQ]=useState('')
  const current=navItems.find(item=>item.to===location.pathname)?.label || 'Dashboard'
  const matches=navItems.filter(item=>item.label.toLowerCase().includes(globalQ.trim().toLowerCase())).slice(0,5)
  const submitSearch=(e:React.FormEvent)=>{e.preventDefault(); const first=matches[0]; if(first){navigate(first.to);setGlobalQ('')}}
  return <div className="app-shell"><aside className={`sidebar ${mobileOpen?'open':''}`}>
    <div className="brand"><div className="brand-mark"><Boxes size={21}/></div><div><strong>Fleet<span>Flow</span></strong><small>Warehouse OS</small></div><button type="button" className="close-mobile" aria-label="Close navigation" onClick={()=>setMobileOpen(false)}><X size={18}/></button></div>
    <div className="workspace-switch"><div className="workspace-dot">P</div><div><b>Pune Central Godown</b><small>Operations workspace</small></div><ChevronRight size={15}/></div>
    <nav>{navItems.map(({label,to,icon:Icon})=><NavLink key={to} to={to} end={to==='/' } onClick={()=>setMobileOpen(false)} className={({isActive})=>isActive?'active':''}><Icon size={17}/><span>{label}</span>{label==='Orders'&&<em>3</em>}</NavLink>)}</nav>
    <div className="sidebar-bottom"><div className="help-card"><ShieldCheck size={18}/><div><b>All systems normal</b><small>Last sync 2 min ago</small></div></div><div className="profile"><Avatar text="AS" color="navy"/><div><b>Arjun Sharma</b><small>Warehouse admin</small></div><ChevronRight size={15}/></div></div>
  </aside><main className="main-content"><header className="topbar"><div className="top-left"><button type="button" className="menu-button" aria-label="Open navigation" onClick={()=>setMobileOpen(true)}><Menu size={20}/></button><div><div className="breadcrumb">Workspace <ChevronRight size={12}/> Operations</div><h1>{current}</h1></div></div><div className="top-actions"><form className="global-search-wrap" onSubmit={submitSearch}><div className="global-search"><Search size={16}/><input aria-label="Search FleetFlow" value={globalQ} onChange={e=>setGlobalQ(e.target.value)} placeholder="Search modules..."/><kbd>↵</kbd></div>{globalQ&&<div className="global-results" role="listbox">{matches.length?matches.map(item=><button type="button" key={item.to} onClick={()=>{navigate(item.to);setGlobalQ('')}}>{item.label}<ChevronRight size={14}/></button>):<span>No matching module</span>}</div>}</form><span className={`backend-status ${dataSource}`} title={loading?'Loading operational data':'Data source'}>{loading?'Syncing…':dataSource==='supabase'?'Supabase':'Mock fallback'}</span><button type="button" className="icon-button notification" aria-label="Notifications"><Bell size={19}/><i/></button><div className="top-avatar">AS</div></div></header><div className="page-content">{children}</div></main></div>
}

function Dashboard({products,inventory,shipments,dispatches,orders,vehicles}:{products:Product[];inventory:InventoryItem[];shipments:Shipment[];dispatches:Dispatch[];orders:Order[];vehicles:Vehicle[]}){
  const navigate=useNavigate();
  const low=inventory.filter(i=>{const p=products.find(x=>x.id===i.productId); return p&&i.available<p.reorderLevel}).length
  const stock=inventory.reduce((sum,i)=>sum+i.available,0); const incoming=shipments.filter(s=>s.arrival.startsWith('Today')).length; const outgoing=dispatches.filter(d=>d.dispatched.startsWith('Today')).length
  return <><div className="page-intro"><div><div className="eyebrow">{new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()).toUpperCase()}</div><h2>Good morning, Arjun <span className="wave">👋</span></h2><p>Here’s what’s happening across your warehouse today.</p></div><div className="intro-actions"><Button variant="secondary" onClick={()=>navigate('/reports')}><CloudDownload size={16}/> Export report</Button><Button onClick={()=>navigate('/orders')}><Plus size={17}/> New order</Button></div></div>
    <div className="stats-grid"><StatCard label="Total products" value={products.length} trend="+2.4% vs last month" icon={<Package size={19}/>} accent="blue"/><StatCard label="Available stock" value={number(stock)} trend="+8.6% vs last week" icon={<Boxes size={19}/>} accent="green"/><StatCard label="Incoming today" value={incoming} trend="2 arriving soon" icon={<ArrowDownRight size={19}/>} accent="amber"/><StatCard label="Pending deliveries" value={orders.filter(o=>o.status==='Pending'||o.status==='In Transit').length} trend="-12.5% vs yesterday" icon={<Truck size={19}/>} accent="purple"/></div>
    <div className="dashboard-grid"><Card className="chart-card"><SectionHeader eyebrow="STOCK MOVEMENT" title="Incoming vs outgoing stock" subtitle="Crates and cases processed this week" action={<Select value="This week" onChange={()=>{}}><option>This week</option><option>Last week</option></Select>}/><ResponsiveContainer width="100%" height={250}><AreaChart data={weeklyFlow}><defs><linearGradient id="incoming" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2b6ff4" stopOpacity={.2}/><stop offset="100%" stopColor="#2b6ff4" stopOpacity={0}/></linearGradient><linearGradient id="outgoing" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#24b47e" stopOpacity={.18}/><stop offset="100%" stopColor="#24b47e" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf1f7"/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fontSize:12,fill:'#8794a9'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:12,fill:'#8794a9'}}/><Tooltip/><Area type="monotone" dataKey="incoming" stroke="#2b6ff4" fill="url(#incoming)" strokeWidth={2.5}/><Area type="monotone" dataKey="outgoing" stroke="#24b47e" fill="url(#outgoing)" strokeWidth={2.5}/></AreaChart></ResponsiveContainer><div className="chart-legend"><span><i className="dot blue-dot"/>Incoming stock</span><span><i className="dot green-dot"/>Outgoing stock</span><b><ArrowUpRight size={15}/> 12.8% total throughput</b></div></Card>
      <Card className="performance-card"><SectionHeader eyebrow="WAREHOUSE HEALTH" title="Performance" subtitle="Live operational score"/><div className="score-ring"><div><strong>92</strong><span>/100</span></div></div><div className="performance-label"><b>Excellent</b><span>Top 10% of your network</span></div><div className="mini-bars"><div><span>Order accuracy</span><b>98%</b><i><em style={{width:'98%'}}/></i></div><div><span>On-time dispatch</span><b>94%</b><i><em style={{width:'94%'}}/></i></div><div><span>Space utilisation</span><b>86%</b><i><em style={{width:'86%'}}/></i></div></div></Card></div>
    <div className="dashboard-bottom"><Card><SectionHeader eyebrow="INVENTORY WATCH" title="Low stock alerts" action={<NavLink className="text-link" to="/inventory">View inventory <ChevronRight size={14}/></NavLink>}/>{low===0?<EmptyState title="Inventory is healthy" description="All products are above their reorder levels."/>:<div className="alert-list">{inventory.filter(i=>{const p=products.find(x=>x.id===i.productId);return p&&i.available<p.reorderLevel}).map(item=>{const p=products.find(x=>x.id===item.productId)!;return <div className="alert-row" key={item.id}><div className="product-symbol">{p.image}</div><div className="alert-copy"><b>{p.name}</b><span>{item.available} {p.unit.toLowerCase()} remaining</span></div><div className="stock-bar"><i style={{width:`${Math.max(16,(item.available/p.reorderLevel)*100)}%`}}/></div><Badge>Reorder</Badge></div>})}</div>}</Card><Card><SectionHeader eyebrow="ACTIVITY FEED" title="Recent activity" action={<NavLink className="text-link" to="/reports">View all <ChevronRight size={14}/></NavLink>}/><div className="activity-list">{activities.map(item=><div className="activity-row" key={item.id}><span className={`activity-dot ${item.tone}`}/><div><b>{item.title}</b><span>{item.detail}</span></div><time>{item.time}</time></div>)}</div></Card></div>
  </>
}

function ProductsPage({products,setProducts}:{products:Product[];setProducts:React.Dispatch<React.SetStateAction<Product[]>>}){
  const [q,setQ]=useState(''); const [category,setCategory]=useState('All categories'); const [modal,setModal]=useState(false); const [editing,setEditing]=useState<Product|null>(null)
  const filtered=products.filter(p=>(p.name+p.brand+p.code).toLowerCase().includes(q.toLowerCase())&&(category==='All categories'||p.category===category))
  const open=(p?:Product)=>{setEditing(p||null);setModal(true)}
  const save=(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const item:Product={id:editing?.id||`p${Date.now()}`,name:String(f.get('name')),brand:String(f.get('brand')),code:String(f.get('code')),category:String(f.get('category')),packageSize:String(f.get('packageSize')),unit:String(f.get('unit')),batch:String(f.get('batch')),expiry:String(f.get('expiry')),reorderLevel:Number(f.get('reorderLevel')),image:editing?.image||'🥤'};setProducts(prev=>editing?prev.map(x=>x.id===editing.id?item:x):[...prev,item]);setModal(false)}
  return <><PageIntro title="Products" subtitle="Manage your beverage catalogue, batches, and reorder rules." action={<Button onClick={()=>open()}><Plus size={17}/> Add product</Button>}/><div className="filter-row"><SearchBox value={q} onChange={setQ} placeholder="Search products, brands, codes..."/><Select value={category} onChange={setCategory}><option>All categories</option><option>Cola</option><option>Lemon Lime</option><option>Orange</option><option>Water</option></Select><span className="result-count">{filtered.length} products</span></div><Card className="table-card"><TableHead columns={['Product','Code / category','Package','Batch & expiry','Reorder level','Actions']}/>{filtered.length===0?<EmptyState title="No products found" description="Try adjusting your search or category filter."/>:<div className="table-body">{filtered.map(p=><div className="table-row" key={p.id}><div className="product-cell"><div className="product-symbol">{p.image}</div><div><b>{p.name}</b><span>{p.brand}</span></div></div><div><b>{p.code}</b><span>{p.category}</span></div><div>{p.packageSize}<span>{p.unit}</span></div><div><b>{p.batch}</b><span>{p.expiry}</span></div><div><b>{p.reorderLevel}</b><span>units</span></div><div className="row-actions"><button className="icon-button" onClick={()=>open(p)} title="Edit"><Pencil size={16}/></button><ConfirmButton onConfirm={()=>setProducts(prev=>prev.filter(x=>x.id!==p.id))}><X size={16}/></ConfirmButton></div></div>)}</div>}</Card><ProductModal open={modal} editing={editing} onClose={()=>setModal(false)} onSave={save}/></>
}
function ProductModal({open,editing,onClose,onSave}:{open:boolean;editing:Product|null;onClose:()=>void;onSave:(e:React.FormEvent<HTMLFormElement>)=>void}){return <Modal open={open} title={editing?'Edit product':'Add product'} onClose={onClose} wide><form onSubmit={onSave}><div className="form-grid"><Field label="Product name"><input name="name" required defaultValue={editing?.name}/></Field><Field label="Brand"><input name="brand" required defaultValue={editing?.brand}/></Field><Field label="Product code"><input name="code" required defaultValue={editing?.code}/></Field><Field label="Category"><select name="category" defaultValue={editing?.category||'Cola'}><option>Cola</option><option>Lemon Lime</option><option>Orange</option><option>Water</option></select></Field><Field label="Package size"><input name="packageSize" required defaultValue={editing?.packageSize||'250 ml'}/></Field><Field label="Unit"><input name="unit" required defaultValue={editing?.unit||'Crate'}/></Field><Field label="Batch number"><input name="batch" required defaultValue={editing?.batch}/></Field><Field label="Expiry date"><input name="expiry" type="date" required defaultValue={editing?.expiry}/></Field><Field label="Reorder level"><input name="reorderLevel" type="number" min="1" required defaultValue={editing?.reorderLevel||50}/></Field></div><div className="modal-actions"><Button type="button" variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit"><Check size={16}/> Save product</Button></div></form></Modal>}

function InventoryPage({products,inventory}:{products:Product[];inventory:InventoryItem[]}){const [q,setQ]=useState('');const [synced,setSynced]=useState('2 mins ago');const rows=inventory.filter(i=>{const p=products.find(x=>x.id===i.productId);return p?.name.toLowerCase().includes(q.toLowerCase())});return <><PageIntro title="Inventory" subtitle="Real-time stock position across every warehouse location." action={<Button variant="secondary" onClick={()=>setSynced('just now')}><RefreshCw size={16}/> Sync inventory</Button>}/><div className="stats-grid compact"><StatCard label="Total available" value={number(inventory.reduce((s,i)=>s+i.available,0))} trend="Across 6 SKUs" icon={<Boxes size={19}/>} accent="green"/><StatCard label="Reserved stock" value={number(inventory.reduce((s,i)=>s+i.reserved,0))} trend="11.4% of total" icon={<ClipboardList size={19}/>} accent="purple"/><StatCard label="Damaged units" value={number(inventory.reduce((s,i)=>s+i.damaged,0))} trend="0.5% shrinkage" icon={<AlertTriangle size={19}/>} accent="amber"/><StatCard label="Locations active" value="12 / 14" trend="2 locations available" icon={<Hash size={19}/>} accent="blue"/></div><div className="filter-row"><SearchBox value={q} onChange={setQ} placeholder="Search inventory..."/><span className="result-count">Updated {synced}</span></div><Card className="table-card"><TableHead columns={['Product','Opening','Incoming','Outgoing','Damaged','Available','Location','Stock health']}/><div className="table-body">{rows.map(i=>{const p=products.find(x=>x.id===i.productId)!;const healthy=i.available>=p.reorderLevel;return <div className="table-row inventory-row" key={i.id}><div className="product-cell"><div className="product-symbol">{p.image}</div><div><b>{p.name}</b><span>{p.code}</span></div></div><div>{number(i.opening)}</div><div className="positive">+{number(i.incoming)}</div><div className="negative">-{number(i.outgoing)}</div><div className="warning">{i.damaged}</div><div><b>{number(i.available)}</b><span>{p.unit}</span></div><div><b>{i.location}</b><span>{i.lastUpdated}</span></div><div><div className="health-line"><i className={healthy?'healthy':''} style={{width:`${Math.min(100,(i.available/(p.reorderLevel*3))*100)}%`}}/></div><span className={healthy?'health-good':'health-low'}>{healthy?'Healthy':'Reorder soon'}</span></div></div>})}</div></Card></>}

function IncomingPage({shipments,setShipments}:{shipments:Shipment[];setShipments:React.Dispatch<React.SetStateAction<Shipment[]>>}){const [tab,setTab]=useState('All shipments');const [modal,setModal]=useState(false);const pending=shipments.filter(s=>s.status==='Pending').length;return <><PageIntro title="Incoming stock" subtitle="Track supplier arrivals, receiving checks, and stock verification." action={<Button onClick={()=>setModal(true)}><Plus size={17}/> Record arrival</Button>}/><div className="kpi-strip"><div><span>Today’s expected</span><b>{number(shipments.filter(s=>s.arrival.startsWith('Today')).reduce((sum,s)=>sum+s.expected,0))} <small>units</small></b></div><div><span>Received</span><b className="green-text">{number(shipments.filter(s=>s.arrival.startsWith('Today')).reduce((sum,s)=>sum+s.received,0))} <small>units</small></b></div><div><span>Awaiting verification</span><b className="amber-text">{pending}</b></div><div><span>Damaged today</span><b>{number(shipments.filter(s=>s.arrival.startsWith('Today')).reduce((sum,s)=>sum+s.damaged,0))} <small>units</small></b></div></div><Tabs items={['All shipments','Arriving today','Pending verification']} active={tab} onChange={setTab}/><Card className="table-card"><TableHead columns={['Shipment','Supplier','Driver / vehicle','Arrival','Expected / received','Status','Action']}/><div className="table-body">{shipments.filter(s=>tab==='All shipments'||(tab==='Arriving today'&&s.arrival.startsWith('Today'))||(tab==='Pending verification'&&s.status==='Pending')).map(s=><div className="table-row" key={s.id}><div><b>{s.id}</b><span>{s.qr}</span></div><div><b>{s.supplier}</b><span>Supplier</span></div><div><b>{s.driver}</b><span>{s.vehicle}</span></div><div>{s.arrival}</div><div><b>{s.received||'—'} / {s.expected}</b><span>received / expected</span></div><div><Badge>{s.status}</Badge></div><div><Button variant="ghost" onClick={()=>setShipments(prev=>prev.map(x=>x.id===s.id?{...x,status:'Verified',received:x.expected}:x))}>{s.status==='Pending'?'Verify':'View'} <ChevronRight size={14}/></Button></div></div>)}</div></Card><ArrivalModal open={modal} onClose={()=>setModal(false)} onSave={shipment=>{setShipments(prev=>[shipment,...prev]);setTab('All shipments');setModal(false)}}/></>}
function ArrivalModal({open,onClose,onSave}:{open:boolean;onClose:()=>void;onSave:(shipment:Shipment)=>void}){return <Modal open={open} title="Record incoming arrival" onClose={onClose} wide><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);const id=`IN-${String(Date.now()).slice(-6)}`;onSave({id,supplier:String(f.get('supplier')),driver:String(f.get('driver')),vehicle:String(f.get('vehicle')),arrival:'Today, just now',expected:Number(f.get('expected')),received:0,damaged:0,status:'Pending',qr:`QR-${id}`});e.currentTarget.reset()}}><div className="form-grid"><Field label="Supplier"><input name="supplier" required placeholder="Supplier name"/></Field><Field label="Driver"><input name="driver" required placeholder="Driver name"/></Field><Field label="Vehicle registration"><input name="vehicle" required placeholder="MH 12 AB 4832"/></Field><Field label="Expected quantity"><input name="expected" type="number" min="1" defaultValue="300" required/></Field></div><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit"><Check size={16}/> Record arrival</Button></div></form></Modal>}
function OutgoingPage({dispatches,setDispatches}:{dispatches:Dispatch[];setDispatches:React.Dispatch<React.SetStateAction<Dispatch[]>>}){
  const [q,setQ]=useState(''); const [modal,setModal]=useState(false)
  const shown=dispatches.filter(d=>(d.id+d.marketer+d.destination+d.product).toLowerCase().includes(q.toLowerCase()))
  return <><PageIntro title="Outgoing stock" subtitle="Manage dispatches, routes, and delivery status." action={<Button onClick={()=>setModal(true)}><Plus size={17}/> Create dispatch</Button>}/><div className="stats-grid compact"><StatCard label="Dispatched today" value={number(dispatches.filter(d=>d.dispatched.startsWith('Today')).reduce((sum,d)=>sum+d.quantity,0))} trend="Local dispatch records" icon={<ArrowUpRight size={19}/>} accent="blue"/><StatCard label="On route" value={dispatches.filter(x=>x.status==='On Route').length} trend="Update delivery status below" icon={<Truck size={19}/>} accent="amber"/><StatCard label="Delivered today" value={dispatches.filter(x=>x.status==='Delivered'&&x.dispatched.startsWith('Today')).length} trend="Local mock data" icon={<Check size={19}/>} accent="green"/></div><div className="filter-row"><SearchBox value={q} onChange={setQ} placeholder="Search dispatches..."/><span className="result-count">{shown.length} dispatches</span></div><Card className="table-card"><TableHead columns={['Dispatch','Marketer / destination','Products','Vehicle / driver','Dispatched','Status','']}/><div className="table-body">{shown.length===0?<EmptyState title="No dispatches found" description="Try a different search or create a new dispatch."/>:shown.map(d=><div className="table-row" key={d.id}><div><b>{d.id}</b><span>{d.quantity} total units</span></div><div><b>{d.marketer}</b><span>{d.destination}</span></div><div><b>{d.product}</b><span>{d.quantity} crates/cases</span></div><div><b>{d.vehicle}</b><span>{d.driver}</span></div><div>{d.dispatched}</div><div><Badge>{d.status}</Badge></div><div><Button variant="ghost" onClick={()=>setDispatches(prev=>prev.map(x=>x.id===d.id?{...x,status:x.status==='On Route'?'Delivered':'On Route'}:x))}>{d.status==='On Route'?'Mark delivered':'Update'} <ChevronRight size={14}/></Button></div></div>)}</div></Card><DispatchModal open={modal} onClose={()=>setModal(false)} onSave={dispatch=>{setDispatches(prev=>[dispatch,...prev]);setModal(false)}}/></>
}
function DispatchModal({open,onClose,onSave}:{open:boolean;onClose:()=>void;onSave:(dispatch:Dispatch)=>void}){return <Modal open={open} title="Create dispatch" onClose={onClose} wide><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave({id:`OUT-${String(Date.now()).slice(-4)}`,marketer:String(f.get('marketer')),product:String(f.get('product')),quantity:Number(f.get('quantity')),vehicle:String(f.get('vehicle')),driver:String(f.get('driver')),dispatched:'Today, just now',destination:String(f.get('destination')),status:'On Route'});e.currentTarget.reset()}}><div className="form-grid"><Field label="Marketer"><input name="marketer" required placeholder="Retail account"/></Field><Field label="Destination"><input name="destination" required placeholder="Area, city"/></Field><Field label="Products"><input name="product" required defaultValue="Sprite + Thums Up"/></Field><Field label="Quantity"><input name="quantity" type="number" min="1" defaultValue="100" required/></Field><Field label="Vehicle"><input name="vehicle" required defaultValue="MH 12 AB 4832"/></Field><Field label="Driver"><input name="driver" required defaultValue="Rakesh Kumar"/></Field></div><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit"><Check size={16}/> Create dispatch</Button></div></form></Modal>}

