function QRPage({shipments}:{shipments:Shipment[]}){const [selected,setSelected]=useState(shipments[0].id);const [scanning,setScanning]=useState(false);const shipment=shipments.find(s=>s.id===selected)!;const downloadCode=()=>{const blob=new Blob([`FleetFlow shipment QR\n${shipment.id}\n${shipment.qr}`],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${shipment.qr}.txt`;a.click();URL.revokeObjectURL(url)};return <><PageIntro title="QR management" subtitle="Identify shipments instantly from receiving dock to delivery bay." action={<Button onClick={()=>setSelected(shipments[0].id)}><QrCode size={17}/> Generate QR code</Button>}/> <div className="qr-layout"><Card className="qr-main"><SectionHeader eyebrow="SHIPMENT IDENTIFICATION" title="Shipment QR code" subtitle="Use a scanner or camera to verify a shipment."/><div className="qr-stage"><div className="fake-qr">{Array.from({length:64}).map((_,i)=><i key={i} className={(i*7+i%3)%5===0?'off':''}/>)}</div><div className="qr-meta"><span>Active code</span><strong>{shipment.qr}</strong><small>Generated for {shipment.id}</small><Button variant="secondary" onClick={downloadCode}><CloudDownload size={15}/> Download code</Button></div></div><div className={`scan-box ${scanning?'scanning':''}`}><div className="scan-icon"><QrCode size={22}/></div><div><b>{scanning?'Scanner simulation active':'Camera scanner ready'}</b><span>{scanning?'Use the shipment registry to simulate a scan result.':'Point a device camera at a shipment QR code to load its details.'}</span></div><Button onClick={()=>setScanning(!scanning)}>{scanning?'Stop scanner':'Start scanner'}</Button></div></Card><Card className="qr-side"><SectionHeader eyebrow="RECENT CODES" title="Shipment registry"/><div className="shipment-list">{shipments.map(s=><button className={selected===s.id?'selected':''} key={s.id} onClick={()=>setSelected(s.id)}><div className="mini-qr"><QrCode size={19}/></div><div><b>{s.id}</b><span>{s.supplier}</span></div><ChevronRight size={15}/></button>)}</div></Card></div></>}

