function MockFleetMap({vehicles}:{vehicles:Vehicle[]}){return <div className="mock-map"><div className="map-gridlines"/><div className="map-road r1"/><div className="map-road r2"/><div className="map-road r3"/><div className="map-label l1">Kothrud</div><div className="map-label l2">Wakad</div><div className="map-label l3">Hadapsar</div><div className="warehouse-pin"><Boxes size={18}/><span>Central Godown</span></div>{vehicles.filter(v=>v.status!=='Maintenance').map((v,i)=><div className={`vehicle-pin pin${i+1}`} key={v.id}><Truck size={16}/><span>{v.registration}</span></div>)}</div>}

function GoogleFleetMap({vehicles}:{vehicles:Vehicle[]}){
  const mapRef=useRef<HTMLDivElement>(null); const mapInstance=useRef<any>(null); const markers=useRef<any[]>([]); const [mode,setMode]=useState<'loading'|'google'|'mock'|'error'>('loading')
  useEffect(()=>{
    const key=import.meta.env.VITE_GOOGLE_MAPS_API_KEY
    if(!key){setMode('mock');return}
    const renderMap=()=>{
      if(!window.google?.maps||!mapRef.current){setMode('error');return}
      if(!mapInstance.current) mapInstance.current=new window.google.maps.Map(mapRef.current,{center:puneCenter,zoom:12,mapTypeControl:false,streetViewControl:false,fullscreenControl:true,styles:[{featureType:'poi',stylers:[{visibility:'off'}]}]})
      markers.current.forEach(marker=>marker.setMap(null));
      markers.current=[new window.google.maps.Marker({map:mapInstance.current,position:puneCenter,title:'Pune Central Godown',label:'W'})]
      vehicles.filter(v=>v.status!=='Maintenance').forEach(vehicle=>{
        const position=locationCoordinates[vehicle.location]||puneCenter
        const marker=new window.google.maps.Marker({map:mapInstance.current,position,title:`${vehicle.registration} • ${vehicle.driver}`,label:'🚚'})
        const info=new window.google.maps.InfoWindow({content:`<div style="font:13px Arial;color:#192536"><strong>${vehicle.registration}</strong><br>${vehicle.driver}<br>${vehicle.location} • ${vehicle.status}<br>ETA: ${vehicle.eta}</div>`})
        marker.addListener('click',()=>info.open({map:mapInstance.current,anchor:marker}))
        markers.current.push(marker)
      })
      setMode('google')
    }
    if(window.google?.maps){renderMap();return}
    const existing=document.getElementById('fleetflow-google-maps') as HTMLScriptElement|null
    const script=existing||document.createElement('script')
    if(!existing){script.id='fleetflow-google-maps';script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&v=weekly`;script.async=true;script.defer=true;document.head.appendChild(script)}
    const loaded=()=>renderMap(); const failed=()=>setMode('error'); script.addEventListener('load',loaded);script.addEventListener('error',failed)
    return()=>{script.removeEventListener('load',loaded);script.removeEventListener('error',failed)}
  },[vehicles])
  if(mode==='mock'||mode==='error') return <><MockFleetMap vehicles={vehicles}/><div className="map-source-note">{mode==='error'?'Google Maps could not load, so FleetFlow is showing the mock map.':'Add VITE_GOOGLE_MAPS_API_KEY to use the interactive map.'}</div></>
  return <div className="google-map-shell"><div ref={mapRef} className="google-map"/><div className="map-overlay-badge">{mode==='google'?'Google Maps • mock vehicle positions':'Loading Google Maps…'}</div></div>
}

function TrackingPage({vehicles}:{vehicles:Vehicle[]}){const [updated,setUpdated]=useState('2 min ago');const activeVehicles=vehicles.filter(v=>v.status!=='Maintenance');return <><PageIntro title="Live tracking" subtitle="Google Maps-ready planning view using mock vehicle positions. Not real GPS tracking." action={<Button variant="secondary" onClick={()=>setUpdated('just now')}><RefreshCw size={16}/> Refresh locations</Button>}/><div className="tracking-grid"><Card className="map-card"><div className="map-head"><div><b>Pune delivery network</b><span>{import.meta.env.VITE_GOOGLE_MAPS_API_KEY?'Google Maps ready':'Mock map fallback'} • updated {updated}</span></div><Badge>{activeVehicles.length} vehicles</Badge></div><GoogleFleetMap vehicles={vehicles}/><div className="map-note"><CircleGauge size={15}/><span>Locations are simulated planning coordinates. Connect a real GPS provider before treating this view as live tracking.</span></div></Card><Card className="track-list"><SectionHeader eyebrow="FLEET STATUS" title="Vehicles on the road"/><div>{vehicles.map(v=><div className="track-row" key={v.id}><span className={`status-pulse ${v.status==='On Route'?'live':''}`}/><div><b>{v.registration}</b><span>{v.driver} • {v.location}</span></div><div className="track-eta"><b>{v.eta}</b><span>{v.status}</span></div></div>)}</div></Card></div></>}

function MarketersPage({marketers,setMarketers}:{marketers:Marketer[];setMarketers:React.Dispatch<React.SetStateAction<Marketer[]>>}){const [q,setQ]=useState('');const [modal,setModal]=useState(false);return <><PageIntro title="Marketers" subtitle="Manage your retail network, account health, and sales performance." action={<Button onClick={()=>setModal(true)}><Plus size={17}/> Add marketer</Button>}/><div className="stats-grid compact"><StatCard label="Active accounts" value={marketers.filter(m=>m.status==='Active').length} trend="4 areas covered" icon={<Users size={19}/>} accent="blue"/><StatCard label="Network revenue" value={money(marketers.reduce((s,m)=>s+m.revenue,0))} trend="+11.8% this quarter" icon={<WalletCards size={19}/>} accent="green"/><StatCard label="Orders this month" value={number(marketers.reduce((s,m)=>s+m.orders,0))} trend="+24 orders this week" icon={<ShoppingCart size={19}/>} accent="purple"/></div><div className="filter-row"><SearchBox value={q} onChange={setQ} placeholder="Search marketers..."/></div><Card className="table-card"><TableHead columns={['Account','Contact','Area','Orders','Revenue','Status','']}/><div className="table-body">{marketers.filter(m=>(m.name+m.area).toLowerCase().includes(q.toLowerCase())).map(m=><div className="table-row" key={m.id}><div className="product-cell"><Avatar text={m.avatar} color="purple"/><div><b>{m.name}</b><span>Account since Jan 2023</span></div></div><div>{m.phone}</div><div>{m.area}</div><div><b>{m.orders}</b><span>orders</span></div><div><b>{money(m.revenue)}</b><span>lifetime value</span></div><div><Badge>{m.status}</Badge></div><div><Button variant="ghost" onClick={()=>setMarketers(prev=>prev.map(x=>x.id===m.id?{...x,status:x.status==='Active'?'Inactive':'Active'}:x))}>{m.status==='Active'?'Pause':'Activate'}</Button></div></div>)}</div></Card><MarketerModal open={modal} onClose={()=>setModal(false)} onSave={marketer=>{setMarketers(prev=>[marketer,...prev]);setModal(false)}}/></>}

function ReportsPage({inventory,products,shipments,dispatches}:{inventory:InventoryItem[];products:Product[];shipments:Shipment[];dispatches:Dispatch[]}){const [report,setReport]=useState('Inventory summary');const exportReport=()=>{const blob=new Blob([JSON.stringify({report,generatedAt:new Date().toISOString(),inventory,products,shipments,dispatches},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='fleetflow-report.json';a.click();URL.revokeObjectURL(url)};return <><PageIntro title="Reports & analytics" subtitle="Understand throughput, shrinkage, and fleet performance." action={<Button onClick={exportReport}><CloudDownload size={16}/> Export report</Button>}/><div className="report-selector"><button className={report==='Inventory summary'?'active':''} onClick={()=>setReport('Inventory summary')}><Boxes size={18}/><b>Inventory summary</b><span>Stock position and health</span></button><button className={report==='Dispatch performance'?'active':''} onClick={()=>setReport('Dispatch performance')}><Truck size={18}/><b>Dispatch performance</b><span>Routes and fulfilment</span></button><button className={report==='Damaged stock'?'active':''} onClick={()=>setReport('Damaged stock')}><AlertTriangle size={18}/><b>Damaged stock</b><span>Loss and shrinkage</span></button></div><div className="reports-grid"><Card className="chart-card"><SectionHeader eyebrow={report.toUpperCase()} title={report==='Inventory summary'?'Stock position by SKU':report==='Dispatch performance'?'Weekly dispatch performance':'Damaged units by product'}/><ResponsiveContainer width="100%" height={300}>{report==='Inventory summary'?<BarChart data={inventory.map(i=>({name:products.find(p=>p.id===i.productId)?.name.split(' ')[0],available:i.available,reserved:i.reserved}))}><CartesianGrid vertical={false} stroke="#edf1f7"/><XAxis dataKey="name" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="available" fill="#2b6ff4" radius={[5,5,0,0]}/><Bar dataKey="reserved" fill="#cad8fb" radius={[5,5,0,0]}/></BarChart>:<AreaChart data={weeklyFlow}><CartesianGrid vertical={false} stroke="#edf1f7"/><XAxis dataKey="day" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Area type="monotone" dataKey="outgoing" stroke={report==='Damaged stock'?'#e5a32b':'#24b47e'} fill={report==='Damaged stock'?'#fff4db':'#e2f7ef'} strokeWidth={3}/></AreaChart>}</ResponsiveContainer></Card><Card className="report-breakdown"><SectionHeader eyebrow="BREAKDOWN" title="Key numbers"/><div className="breakdown-list"><div><span>Total incoming</span><b>{number(shipments.reduce((s,x)=>s+x.received,0))}</b></div><div><span>Total dispatched</span><b>{number(dispatches.reduce((s,x)=>s+x.quantity,0))}</b></div><div><span>Damage rate</span><b>0.7%</b></div><div><span>Stock accuracy</span><b className="green-text">98.4%</b></div></div><div className="report-note"><BarChart3 size={18}/><span>Reports use local mock data and can be exported for review.</span></div></Card></div></>}

